package academy.student;

public record Student(String id, String name) {
  public Student {
    if (id == null || id.isBlank()) throw new IllegalArgumentException("id is required");
    if (name == null || name.isBlank()) throw new IllegalArgumentException("name is required");
  }
}

package academy.student;

import java.util.Optional;

public interface StudentRepository {
  void save(Student student);
  Optional<Student> findById(String id);
}

package academy.student;

import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

public final class InMemoryStudentRepository implements StudentRepository {
  private final Map<String, Student> students = new HashMap<>();

  @Override
  public void save(Student student) {
    students.put(student.id(), student);
  }

  @Override
  public Optional<Student> findById(String id) {
    return Optional.ofNullable(students.get(id));
  }
}

package academy.student;

public final class StudentService {
  private final StudentRepository repository;

  public StudentService(StudentRepository repository) {
    if (repository == null) throw new IllegalArgumentException("repository is required");
    this.repository = repository;
  }

  public Student register(String id, String name) {
    if (repository.findById(id).isPresent()) {
      throw new IllegalStateException("student already exists: " + id);
    }
    Student student = new Student(id, name);
    repository.save(student);
    return student;
  }
}

package academy.student;

public final class StudentApplication {
  public static void main(String[] args) {
    StudentRepository repository = new InMemoryStudentRepository();
    StudentService service = new StudentService(repository);

    Student student = service.register("STU-101", "Ravi");
    System.out.println("Registered: " + student);
  }
}

